using Rocker.Domain;
internal static class PracticeSessionChecks
{
    public static void Run(Action<bool,string> check)
    {
        var wall=new DateTimeOffset(2026,10,11,12,0,0,TimeSpan.Zero);var session=new PracticeSession();
        session.Observe(0,wall,TimeZoneInfo.Utc,true);session.Observe(1000,wall.AddSeconds(1),TimeZoneInfo.Utc,true);check(session.TotalMs==0 && session.Drain().Count==0,"opening a page or receiving evidence without an explicit session never counts time");
        session.Start(1000,wall.AddSeconds(1));session.Observe(2000,wall.AddSeconds(2),TimeZoneInfo.Utc,false);session.Observe(3000,wall.AddSeconds(3),TimeZoneInfo.Utc,false);check(session.TotalMs==0,"a running but idle session still charges no practice");
        session.Observe(4000,wall.AddSeconds(4),TimeZoneInfo.Utc,true);session.Observe(5000,wall.AddSeconds(5),TimeZoneInfo.Utc,true);check(session.TotalMs==1000,"observed activity charges only the evidenced interval once");session.Observe(5000,wall.AddSeconds(5),TimeZoneInfo.Utc,true);check(session.TotalMs==1000,"duplicate refresh cannot charge the same interval twice");
        session.Pause();session.Observe(6000,wall.AddSeconds(6),TimeZoneInfo.Utc,true);check(session.TotalMs==1000,"pause excludes otherwise valid input/playback evidence");session.Resume();session.Observe(7000,wall.AddSeconds(7),TimeZoneInfo.Utc,true);session.Observe(8000,wall.AddSeconds(8),TimeZoneInfo.Utc,true);check(session.TotalMs==2000,"resume requires a fresh observed activity interval");
        var wake=session.Observe(608000,wall.AddSeconds(608),TimeZoneInfo.Utc,true);check(wake.GapDiscarded && wake.ChargedMs==0 && session.TotalMs==2000,"a sleep or stalled UI gap never manufactures elapsed playing time");session.Observe(609000,wall.AddSeconds(609),TimeZoneInfo.Utc,true);session.Observe(610000,wall.AddSeconds(610),TimeZoneInfo.Utc,true);check(session.TotalMs==3000,"normal observed activity can resume after the discarded sleep gap");
        check(Math.Abs(session.Drain().Values.Sum()-3000.0/60000)<1e-9 && session.Drain().Count==0,"daily increments drain exactly once");session.End();session.Observe(611000,wall.AddSeconds(611),TimeZoneInfo.Utc,true);check(session.TotalMs==3000,"ended session cannot charge additional time");var restarted=new PracticeSession();restarted.Observe(612000,wall.AddSeconds(612),TimeZoneInfo.Utc,true);check(restarted.TotalMs==0,"restart is idle and never reconstructs an unfinished clock segment");
        foreach(var offset in new[]{TimeSpan.Zero,TimeSpan.FromMinutes(345)})
        {
            var zone=TimeZoneInfo.CreateCustomTimeZone("test",offset,"test","test");var start=new DateTimeOffset(2026,10,11,23,59,58,500,offset);var midnight=new PracticeSession();midnight.Start(0,start);midnight.Observe(1000,start.AddSeconds(1),zone,true);midnight.Observe(2000,start.AddSeconds(2),zone,true);var days=midnight.Drain();check(days.Count==2 && Math.Abs(days["2026-10-11"]-.5/60)<1e-9 && Math.Abs(days["2026-10-12"]-.5/60)<1e-9,"midnight splits a real interval exactly in both UTC and a non-hour time zone");
        }
        var change=new PracticeSession();change.Start(0,wall);change.Observe(1000,wall.AddSeconds(1),TimeZoneInfo.Utc,true);change.Observe(2000,wall.AddSeconds(2),TimeZoneInfo.Utc,true);change.Observe(3000,wall.AddSeconds(3),TimeZoneInfo.CreateCustomTimeZone("new-zone",TimeSpan.FromHours(14),"new","new"),true);var changedDays=change.Drain();check(changedDays.Count==2 && Math.Abs(changedDays.Values.Sum()-2.0/60)<1e-9,"changing zones preserves previously recorded days and never double-counts the clock");
        var back=change.Observe(4000,wall.AddHours(-1),TimeZoneInfo.Utc,true);check(back.GapDiscarded && back.ChargedMs==0,"backward wall-clock adjustment never corrupts day allocation");
        var eastern=TimeZoneInfo.FindSystemTimeZoneById("America/New_York");var fallStart=new DateTimeOffset(2026,11,1,5,59,58,TimeSpan.Zero);var fall=new PracticeSession();fall.Start(0,fallStart);fall.Observe(1000,fallStart.AddSeconds(1),eastern,true);fall.Observe(2000,fallStart.AddSeconds(2),eastern,true);check(fall.TotalMs==1000 && fall.Drain().Count==1,"the repeated DST hour does not add an hour of practice");
        var rest=new PracticeSession();rest.Start(0,wall);rest.Observe(1,wall.AddMilliseconds(1),TimeZoneInfo.Utc,true);int reminders=0;for(int n=1;n<=2701;++n)if(rest.Observe(1+n*1000,wall.AddMilliseconds(1+n*1000),TimeZoneInfo.Utc,true).Remind)++reminders;check(reminders==1 && rest.Break.Reminded,"45 active minutes produce one reminder, not repeated dialogs");rest.Pause();rest.Observe(3001001,wall.AddMilliseconds(3001001),TimeZoneInfo.Utc,false);check(rest.Break.PracticedMs==0 && !rest.Break.Reminded,"five actual idle minutes reset the continuous-practice reminder");
        foreach(string style in ToneAdvisor.Styles.Keys){var advice=ToneAdvisor.Recommend(InstrumentProfile.Default,style);check(advice.Eq.Length>0 && advice.Note.Length>0 && InstrumentProfile.Default.Pickups.Any(p=>p.Position==advice.Pickup),"every original style resolves a real available pickup");}
        var onlyMiddle=InstrumentProfile.Default with{Pickups=[new("middle","single")]};check(ToneAdvisor.Recommend(onlyMiddle,"metal-rhythm").Pickup=="middle","nearest existing pickup replaces an unavailable preferred position");check(ToneAdvisor.Recommend(onlyMiddle,"metal-rhythm").Note.Contains("single",StringComparison.Ordinal),"high-gain single-coil caveat is preserved");check(ToneAdvisor.Recommend(InstrumentProfile.Default with{Pickups=[]},"clean").Note.Contains("nemá zadané",StringComparison.Ordinal),"missing pickups produce honest advisory status");
        var settings=new AppSettings(ResumeTask:new("06","intro"),PracticePlan:new("day:2026-10-11",new[]{"tune"}),AiPlanProgress:new("ai:123",new[]{"0"}),KeepAwake:true);var saved=UserData.Read<AppSettings>(UserData.Document("settings","default",settings).Value);check(saved.ResumeTask==settings.ResumeTask && saved.KeepAwake && saved.PracticePlan!.Completed[0]=="tune" && saved.AiPlanProgress!.Completed[0]=="0","independent daily/AI completion and exact resume survive persistence");
        bool bad=false;try{UserData.Document("settings","default",settings with{ResumeTask=new("https://outside")});}catch(ArgumentException){bad=true;}check(bad,"saved resume cannot supply an external route");
    }
}
